SELECT  *
	FROM REP_REVEAL
WHERE
1=1

	AND REP_ID = #{repId,jdbcType=VARCHAR}


	AND REPORT_NAME = #{reportName,jdbcType=VARCHAR}


	AND PRODID = #{prodId,jdbcType=VARCHAR}


	AND to_char(START_DATE,'yyyy-MM-dd') = #{startDate,jdbcType=VARCHAR}


	AND  to_char(END_DATE,'yyyy-MM-dd') = #{endDate,jdbcType=VARCHAR}

AND STATUS = 'E'
AND rownum = 1

mapper.update:
update REP_REVEAL
set STATUS = 'D'
WHERE
1=1

	AND REP_ID = #{repId,jdbcType=VARCHAR}


	AND REPORT_NAME = #{reportName,jdbcType=VARCHAR}


	AND PRODID = #{prodId,jdbcType=VARCHAR}


	AND to_char(START_DATE,'yyyy-MM-dd') = #{startDate,jdbcType=VARCHAR}


	AND  to_char(END_DATE,'yyyy-MM-dd') = #{endDate,jdbcType=VARCHAR}

AND STATUS = 'E'
